def _decode_embedded_runner_source():
    raw = Base64.getDecoder().decode("".join(EMBEDDED_RUNNER_GZIP_BASE64_CHUNKS))
    stream = GZIPInputStream(ByteArrayInputStream(raw))
    out = ByteArrayOutputStream()
    buf = zeros(8192, "b")
    try:
        while True:
            count = stream.read(buf, 0, len(buf))
            if count < 0:
                break
            out.write(buf, 0, count)
    finally:
        try:
            stream.close()
        except Exception:
            pass
    return str(out.toString("UTF-8"))


_runner_source = _decode_embedded_runner_source()
